    private static Formula Variable(string name) => name.EndsWith("'", StringComparison.Ordinal) ? Seq(F.Id(name[..^1]), Apos) : F.Id(name);
    private static Formula C(string name) => name is "n" or "k" ? Variable(name) : Seq(Operatorname, Grp(F.Id(name)));
    private static Formula App(Formula function, params Formula[] arguments) => new Formula.Apply(function, [.. arguments]);
    private static Formula All(string name, Formula type, Formula body) => Seq(Forall, Sp, Parenthesized(Seq(Variable(name), Colon, Sp, type)), Comma, Sp, body);
    private static Formula Some(string name, Formula type, Formula body) => Seq(Exists, Sp, Parenthesized(Seq(Variable(name), Colon, Sp, type)), Comma, Sp, body);
    private static Formula Parenthesized(Formula value) => Seq(Open, value, Close);
